import RNA, random, sys, time
target = open('/tmp/target.txt').read().strip()
n = len(target)
pairs = []
stack = []
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs.append((j,i))
tm = {}
for (i,j) in pairs:
    tm[i]=j; tm[j]=i
unpaired = [i for i in range(n) if i not in tm]
md = RNA.md(); md.dangles=2; md.temperature=37.0

def fold(seq):
    fc = RNA.fold_compound(seq, md)
    return fc.mfe()

def bpdist(mfe): return RNA.bp_distance(mfe, target)

def rand_init(seed):
    random.seed(seed)
    seq=list('A'*n)
    for i in unpaired: seq[i]=random.choice('AU')
    for (i,j) in pairs:
        r=random.random()
        if r<0.7:
            if random.random()<0.5: seq[i]='G';seq[j]='C'
            else: seq[i]='C';seq[j]='G'
        else:
            if random.random()<0.5: seq[i]='A';seq[j]='U'
            else: seq[i]='U';seq[j]='A'
    return ''.join(seq)

def guided_mut(seq,mfe):
    s=list(seq)
    mm={}; st=[]
    for i,c in enumerate(mfe):
        if c=='(':st.append(i)
        elif c==')':
            j=st.pop();mm[i]=j;mm[j]=i
    fix=[]; 
    for (i,j) in pairs:
        if mm.get(i)!=j: fix.extend([i,j])
    spurious=[i for (i,j) in mm.items() if tm.get(i)!=j]
    if spurious:
        for i in random.sample(spurious,min(2,len(spurious))):
            s[i]=random.choice('AU')
    elif fix:
        for i in random.sample(fix,min(2,len(fix))):
            if i in tm:
                j=tm[i]
                if random.random()<0.5: s[i]='G';s[j]='C'
                else: s[i]='C';s[j]='G'
    else:
        for _ in range(2):
            i=random.randrange(n);s[i]=random.choice('ACGU')
    return ''.join(s)

